17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.validation.FieldError;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	
56	    /**
57	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
58	     * class.
59	     *
60	     * @param e     Object referring to the thrown exception.
61	     * @param status HTTP response status.
62	     * @param url URL request.
63	     */
64	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
65	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
66	        problemDetail.setType(URI.create(url.toString()));
67	        problemDetail.setTitle(e.getClass().getSimpleName());
68	        problemDetail.setDetail(detail);
69	        problemDetail.setProperty("timestamp", Instant.now());
70	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
71	        return problemDetail;
72	    }
73	
74	    /**
75	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
76	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
77	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
78	     * would catch it and report an authorization failure as a 500.
79	     *
80	     * @param e The {@link AccessDeniedException} to propagate
81	     * @throws AccessDeniedException always
82	     */
83	    @ExceptionHandler(AccessDeniedException.class)
84	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
85	        throw e;
86	    }
87	
88	    /**
89	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
90	     *
91	     * @param e The {@link Exception} to be handled
92	     * @param request {@link HttpServletRequest} object referring to the current request.
93	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
94	     */
95	    @ExceptionHandler(Exception.class)
96	    @ResponseBody
97	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
98	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
99	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
100	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
101	        return ResponseEntity.status(status).body(detail);
102	    }
103	
104	    /**
105	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
106	     * method returns a 404 Not Found status if an entity does not exist.
107	     *
108	     * @param e The {@link DataIntegrityViolationException} to be handled
109	     * @param request {@link HttpServletRequest} object referring to the current request.
110	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
111	     */
112	    @ExceptionHandler(DataIntegrityViolationException.class)
113	    @ResponseBody
114	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
115	        logger.warn("Data integrity violation at {} {}: {}",
116	            request.getMethod(),
117	            request.getRequestURI(),
118	            e.getMessage());
119	        logger.debug("Data integrity violation stacktrace", e);
120	        HttpStatus status = HttpStatus.NOT_FOUND;
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles exception thrown by Bean Validation on controller methods parameters
127	     *
128	     * @param e The {@link MethodArgumentNotValidException} to be handled
129	     * @param request {@link HttpServletRequest} object referring to the current request.
130	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
131	     */
132	    @ExceptionHandler(MethodArgumentNotValidException.class)
133	    @ResponseBody
134	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
135	        HttpStatus status = HttpStatus.BAD_REQUEST;
136	        BindingResult bindingResult = e.getBindingResult();
137	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
138	        if (bindingResult.hasErrors()) {
139	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
140	                .map(this::toValidationMessage)
141	                .toList();
142	            logger.debug("Validation error at {} {}: {}",
143	                request.getMethod(),
144	                request.getRequestURI(),
145	                bindingResult.getFieldErrors());
146	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
147	            List<String> errors = bindingResult.getFieldErrors().stream()
148	                .map(FieldError::getField)
149	                .distinct()
150	                .toList();
151	            detail.setProperty("errors", errors);
152	        }
153	        return ResponseEntity.status(status).body(detail);
154	    }
155	
156	    /**
157	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created or updated with a
158	     * required field missing or blank. Returns a 400 Bad Request whose {@code errors} array lists the
159	     * name of each offending field.
160	     *
161	     * @param e The {@link MissingOwnerFieldsException} to be handled
162	     * @param request {@link HttpServletRequest} object referring to the current request.
163	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
164	     */
165	    @ExceptionHandler(MissingOwnerFieldsException.class)
166	    @ResponseBody
167	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
168	        HttpStatus status = HttpStatus.BAD_REQUEST;
169	        logger.debug("Missing owner fields at {} {}: {}",
170	            request.getMethod(),
171	            request.getRequestURI(),
172	            e.getMissingFields());
173	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
174	        detail.setProperty("errors", e.getMissingFields());
175	        return ResponseEntity.status(status).body(detail);
176	    }
177	
178	    /**
179	     * Handles {@link InvalidOwnerFieldsException} raised when an owner is created or updated with a
180	     * field that is present but malformed (for example a telephone that does not reduce to exactly ten
181	     * digits). Returns a 400 Bad Request whose {@code errors} array lists the name of each offending
182	     * field.
183	     *
184	     * @param e The {@link InvalidOwnerFieldsException} to be handled
185	     * @param request {@link HttpServletRequest} object referring to the current request.
186	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
187	     */
188	    @ExceptionHandler(InvalidOwnerFieldsException.class)
189	    @ResponseBody
190	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
191	        HttpStatus status = HttpStatus.BAD_REQUEST;
192	        logger.debug("Invalid owner fields at {} {}: {}",
193	            request.getMethod(),
194	            request.getRequestURI(),
195	            e.getInvalidFields());
196	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
197	        detail.setProperty("errors", e.getInvalidFields());
198	        return ResponseEntity.status(status).body(detail);
199	    }
200	
201	    /**
202	     * Handles {@link DuplicateOwnerIdentityException} raised when an owner is created whose derived
203	     * {@code identityKey} exactly matches an existing owner's. The identity key consolidates the
204	     * former telephone, email and household duplicate checks into one, so any duplicate collision is
205	     * reported here as a 409 Conflict.
206	     *
207	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
208	     * @param request {@link HttpServletRequest} object referring to the current request.
209	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
210	     */
211	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
212	    @ResponseBody
213	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
214	        HttpStatus status = HttpStatus.CONFLICT;
215	        logger.debug("Duplicate owner identity at {} {}: {}",
216	            request.getMethod(),
217	            request.getRequestURI(),
218	            e.getIdentityKey());
219	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
220	        detail.setProperty("errors", List.of("identityKey"));
221	        return ResponseEntity.status(status).body(detail);
222	    }
223	
224	    /**
225	     * Handles {@link OwnerCityFullException} raised when an owner is created in a city that already
226	     * contains 50 or more owners. Returns a 409 Conflict.
227	     *
228	     * @param e The {@link OwnerCityFullException} to be handled
229	     * @param request {@link HttpServletRequest} object referring to the current request.
230	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
231	     */
232	    @ExceptionHandler(OwnerCityFullException.class)
233	    @ResponseBody
234	    public ResponseEntity<ProblemDetail> handleOwnerCityFullException(OwnerCityFullException e, HttpServletRequest request) {
235	        HttpStatus status = HttpStatus.CONFLICT;
236	        logger.debug("Owner city at capacity at {} {}: {}",
237	            request.getMethod(),
238	            request.getRequestURI(),
239	            e.getCity());
240	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
241	        detail.setProperty("errors", List.of("city"));
242	        return ResponseEntity.status(status).body(detail);
243	    }
244	
245	    /**
246	     * Handles {@link OwnerDailyLimitException} raised when an owner is created after 100 or more
247	     * owners have already been registered today (by {@code registrationDate}). Returns a 429 Too
248	     * Many Requests.
249	     *
250	     * @param e The {@link OwnerDailyLimitException} to be handled
251	     * @param request {@link HttpServletRequest} object referring to the current request.
252	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
253	     */
254	    @ExceptionHandler(OwnerDailyLimitException.class)
255	    @ResponseBody
256	    public ResponseEntity<ProblemDetail> handleOwnerDailyLimitException(OwnerDailyLimitException e, HttpServletRequest request) {
257	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
258	        logger.debug("Owner daily create limit reached at {} {}: {}",
259	            request.getMethod(),
260	            request.getRequestURI(),
261	            e.getRegistrationDate());
262	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
263	        detail.setProperty("errors", List.of("registrationDate"));
